// Stop early with a clear message if Settings still holds the template placeholders.
function checkSettings(s, keys) {
  const unset = keys.filter(k => !String(s[k] ?? '').trim() || String(s[k]).includes('REPLACE_ME'));
  if (unset.length) {
    throw new Error('Open the Settings node and fill in: ' + unset.join(', ') + '. They still contain REPLACE_ME placeholders.');
  }
}

// Work out the last full period (week or month) and the one before it,
// then total the rows in each. Numbers are computed here, never by the AI.
const s = $('Settings').first().json;
checkSettings(s, ['spreadsheetId', 'sheetName', 'sendTo']);
const period = String(s.period || 'week').toLowerCase() === 'month' ? 'month' : 'week';

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
if (rows.length && !(s.dateColumn in rows[0])) {
  throw new Error(`Column "${s.dateColumn}" not found in the sheet. Columns are: ${Object.keys(rows[0]).join(', ')}. Fix dateColumn in Settings.`);
}
if (rows.length && !(s.amountColumn in rows[0])) {
  throw new Error(`Column "${s.amountColumn}" not found in the sheet. Columns are: ${Object.keys(rows[0]).join(', ')}. Fix amountColumn in Settings.`);
}

// Dates: ISO (2026-11-03), Sheets serial numbers (46329), or 11/3/2026 read as dateOrder (MDY or DMY).
function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' || /^\d{5}(\.\d+)?$/.test(String(v))) {
    return DateTime.fromMillis(Math.round((Number(v) - 25569) * 86400000), { zone: 'utc' }).setZone('local', { keepLocalTime: true });
  }
  const t = String(v).trim();
  let d = DateTime.fromISO(t);
  if (d.isValid) return d;
  const m = t.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})/);
  if (m) {
    const [a, b] = [Number(m[1]), Number(m[2])];
    let y = Number(m[3]); if (y < 100) y += 2000;
    const dmy = String(s.dateOrder || 'MDY').toUpperCase() === 'DMY';
    d = DateTime.fromObject({ year: y, month: dmy ? b : a, day: dmy ? a : b });
    if (d.isValid) return d;
  }
  d = DateTime.fromJSDate(new Date(t));
  return d.isValid ? d : null;
}

// Amounts: 1234.5, "$1,234.50", "(45.00)" for negatives, "1.234,50" European style.
function parseAmount(v) {
  if (typeof v === 'number') return v;
  let t = String(v ?? '').trim();
  if (!t) return null;
  const negative = /^\(.*\)$/.test(t) || /^-/.test(t) || /-$/.test(t);
  t = t.replace(/[^\d.,]/g, '');
  if (/,\d{1,2}$/.test(t) && !/\.\d{1,2}$/.test(t)) t = t.replace(/\./g, '').replace(',', '.');
  else t = t.replace(/,/g, '');
  const n = parseFloat(t);
  if (isNaN(n)) return null;
  return negative ? -n : n;
}

const now = DateTime.now();
const start = now.startOf(period).minus({ [period + 's']: 1 });
const end = start.plus({ [period + 's']: 1 });
const prevStart = start.minus({ [period + 's']: 1 });

const current = [], previous = [];
let skipped = 0;
for (const r of rows) {
  const d = parseDate(r[s.dateColumn]);
  const amount = parseAmount(r[s.amountColumn]);
  if (!d || amount === null) { skipped++; continue; }
  const row = {
    date: d,
    amount,
    group: String(r[s.groupColumn] ?? '').trim() || '(none)',
    label: String(r[s.labelColumn] ?? '').trim(),
  };
  if (d >= start && d < end) current.push(row);
  else if (d >= prevStart && d < start) previous.push(row);
}

const sum = list => Math.round(list.reduce((a, r) => a + r.amount, 0) * 100) / 100;
const pct = (a, b) => (b ? Math.round(((a - b) / Math.abs(b)) * 1000) / 10 : null);

const total = sum(current);
const prevTotal = sum(previous);
const groupNames = [...new Set([...current, ...previous].map(r => r.group))];
const groups = groupNames.map(g => {
  const cur = sum(current.filter(r => r.group === g));
  const prev = sum(previous.filter(r => r.group === g));
  return {
    group: g,
    total: cur,
    count: current.filter(r => r.group === g).length,
    share: total ? Math.round((cur / total) * 1000) / 10 : 0,
    previous: prev,
    changePct: pct(cur, prev),
  };
}).filter(g => g.total !== 0 || g.previous !== 0).sort((a, b) => b.total - a.total);

const largest = [...current].sort((a, b) => b.amount - a.amount).slice(0, 5).map(r => ({
  date: r.date.toISODate(), label: r.label, group: r.group, amount: r.amount,
}));

const fmtRange = period === 'week'
  ? `${start.toFormat('LLL d')} to ${end.minus({ days: 1 }).toFormat('LLL d, yyyy')}`
  : start.toFormat('LLLL yyyy');

const stats = {
  report: s.reportTitle,
  period: fmtRange,
  currency: s.currency,
  total, count: current.length,
  average: current.length ? Math.round((total / current.length) * 100) / 100 : 0,
  previousPeriodTotal: prevTotal,
  previousPeriodCount: previous.length,
  changePct: pct(total, prevTotal),
  byGroup: groups.slice(0, 10),
  largestItems: largest,
  rowsSkipped: skipped,
};

return [{ json: { ...stats, hasData: current.length > 0 || previous.length > 0, statsJson: JSON.stringify(stats, null, 2) } }];

// Build the HTML email: AI summary on top, then the exact numbers in tables.
const r = $('Calculate Report').first().json;
const summary = String(($json && $json.text) || '').trim();

const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = n => {
  try { return new Intl.NumberFormat('en-US', { style: 'currency', currency: r.currency || 'USD' }).format(n); }
  catch (e) { return (r.currency || '') + ' ' + Number(n).toFixed(2); }
};
const change = p => (p === null || p === undefined ? '–' : (p > 0 ? '+' : '') + p + '%');
const td = 'style="padding:4px 10px;border-bottom:1px solid #eee"';
const tdr = 'style="padding:4px 10px;border-bottom:1px solid #eee;text-align:right"';
const th = 'style="padding:4px 10px;border-bottom:2px solid #ccc;text-align:left"';

let body;
if (!r.hasData) {
  body = `<p>No rows were dated in ${esc(r.period)} or the period before.</p>` +
    (r.rowsSkipped ? `<p>${r.rowsSkipped} rows were skipped because their date or amount could not be read. Check the dateColumn, amountColumn and dateOrder settings.</p>` : '');
} else {
  const groups = r.byGroup.map(g =>
    `<tr><td ${td}>${esc(g.group)}</td><td ${tdr}>${money(g.total)}</td><td ${tdr}>${g.count}</td><td ${tdr}>${g.share}%</td><td ${tdr}>${change(g.changePct)}</td></tr>`).join('');
  const largest = r.largestItems.map(i =>
    `<tr><td ${td}>${esc(i.date)}</td><td ${td}>${esc(i.label)}</td><td ${td}>${esc(i.group)}</td><td ${tdr}>${money(i.amount)}</td></tr>`).join('');

  body = (summary ? `<p style="font-size:15px;line-height:1.5">${esc(summary)}</p>` : '') +
    `<table style="border-collapse:collapse;margin:12px 0">
      <tr><td ${td}>Total</td><td ${tdr}><b>${money(r.total)}</b></td></tr>
      <tr><td ${td}>Items</td><td ${tdr}>${r.count}</td></tr>
      <tr><td ${td}>Average</td><td ${tdr}>${money(r.average)}</td></tr>
      <tr><td ${td}>Previous period</td><td ${tdr}>${money(r.previousPeriodTotal)} (${r.previousPeriodCount} items)</td></tr>
      <tr><td ${td}>Change</td><td ${tdr}>${change(r.changePct)}</td></tr>
    </table>` +
    (groups ? `<h3 style="margin:18px 0 6px">By group</h3><table style="border-collapse:collapse"><tr><th ${th}>Group</th><th ${th}>Total</th><th ${th}>Items</th><th ${th}>Share</th><th ${th}>vs previous</th></tr>${groups}</table>` : '') +
    (largest ? `<h3 style="margin:18px 0 6px">Largest items</h3><table style="border-collapse:collapse"><tr><th ${th}>Date</th><th ${th}>Item</th><th ${th}>Group</th><th ${th}>Amount</th></tr>${largest}</table>` : '') +
    (r.rowsSkipped ? `<p style="color:#666">${r.rowsSkipped} rows were skipped because their date or amount could not be read.</p>` : '');
}

const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:680px">
<h2 style="margin:0 0 4px">${esc(r.report)}</h2>
<p style="color:#666;margin:0 0 14px">${esc(r.period)}</p>
${body}
</div>`;

return [{ json: { subject: `${r.report}: ${r.period}`, html } }];
